// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;

    function setUp() public {
        c = new PrivatePool(address(this), address(this), address(this));
    }

    function testFuzz_property(
        address baseTokenArg,
        address nftArg,
        uint128 vBase,
        uint128 vNft,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useOracle,
        bool payRoy
    ) public {
        // keep params in the admissible domain: base token must differ from nft
        vm.assume(baseTokenArg != nftArg);
        feeRate = uint16(bound(feeRate, 0, 5_000));

        c.initialize(
            baseTokenArg,
            nftArg,
            vBase,
            vNft,
            changeFee,
            feeRate,
            merkleRoot,
            useOracle,
            payRoy
        );

        // General rule: initialize stores the given _baseToken as baseToken.
        assertTrue(c.baseToken() == baseTokenArg);
    }
}
